test('invoiceTotals with multiple lines and discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 20 },
    ],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 5 * 8500 + 10 * 9500);
  assert.equal(totals.discount, (5 * 8500 * 10) / 100 + (10 * 9500 * 20) / 100);
  assert.equal(totals.total, totals.subtotal - totals.discount);
});

test('invoiceTotals clamps total to 0', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100, discountPercent: 150 }],
  };
  const totals = invoiceTotals(invoice);
  assert.ok(totals.total >= 0);
});

test('addLine accepts discountPercent', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 15 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 15);
});

test('addLine rejects invalid discountPercent', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(addLine(r1.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 200 }), {
    ok: false,
    error: 'DISCOUNT_INVALID',
  });
});

test('addLine updates discount when adding to existing SKU', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  const r2 = addLine(r1.value, { sku: 'DES-HOUR', qty: 3, discountPercent: 20 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[0].qty, 8);
  assert.equal(r2.value.lines[0].discountPercent, 20);
});

test('createInvoice applies tier discount for gold customers', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 5);
});

test('createInvoice applies tier discount for silver customers', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 2.5);
});

test('createInvoice applies no discount for standard tier', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, undefined);
});

test('createInvoice uses explicit discountPercent over tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 15 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 15);
});

test('createInvoice allows explicit 0 discount to override tier', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, undefined);
});

test('addLine applies tier discount for new lines', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 5);
});

test('addLine uses explicit discountPercent over tier', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 10 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 10);
});

test('createInvoice with multiple lines applies tier discount to each', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 5);
  assert.equal(r.value.lines[1].discountPercent, 5);
});

test('createInvoice with mixed discounts applies tier and explicit', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 15 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 5);
  assert.equal(r.value.lines[1].discountPercent, 15);
});

test('lineVat calculates VAT on line total without discount', () => {
  const line = { qty: 100, unitPrice: 1000, vatRate: 21 };
  assert.equal(lineVat(line), 21000);
});

test('lineVat calculates VAT on line total after discount', () => {
  const line = { qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 10 };
  const total = 100000;
  const discount = 10000;
  const afterDiscount = 90000;
  const vat = Math.round(afterDiscount * 0.21);
  assert.equal(lineVat(line), vat);
});

test('lineVat handles 0% VAT', () => {
  const line = { qty: 1, unitPrice: 60000, vatRate: 0 };
  assert.equal(lineVat(line), 0);
});

test('lineVat rounds to nearest cent', () => {
  const line = { qty: 3, unitPrice: 100, vatRate: 33.33 };
  const vat = lineVat(line);
  assert.ok(Number.isInteger(vat));
});

test('lineVat clamps to 0', () => {
  const line = { qty: 1, unitPrice: 50, vatRate: 0, discountPercent: 0 };
  assert.equal(lineVat(line), 0);
});

test('invoiceTotals returns vat field', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const totals = invoiceTotals(r.value);
  assert.ok('vat' in totals);
});

test('invoiceTotals calculates VAT as sum of line VATs', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const line1Vat = Math.round(5 * 8500 * 0.21);
  const line2Vat = Math.round(10 * 9500 * 0.21);
  assert.equal(totals.vat, line1Vat + line2Vat);
});

test('invoiceTotals calculates total including VAT', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('invoiceTotals with discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

test('invoiceTotals with 0% VAT lines', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals mixed VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const line1Vat = Math.round(5 * 8500 * 0.21);
  const line2Vat = Math.round(100 * 37 * 0.09);
  assert.equal(totals.vat, line1Vat + line2Vat);
});

